"""
Learning summary display for Level C - Inventory & Composition.

Engine-owned. Students do NOT edit this file.
"""


def show_level_c_summary(player, items_added, items_removed):
    """
    Show what the student learned in Level C.
    
    Args:
        player: The Player object
        items_added: List of items that were added
        items_removed: List of items that were removed
    """
    print()
    print("=" * 50)
    print("  📚 LEARNING SUMMARY")
    print("=" * 50)
    print()
    print("You just used COMPOSITION to give Player an Inventory:")
    print()
    print("  Your Player HAS-A Inventory (composition)")
    print("    → player.inventory = Inventory()")
    print()
    print("  You called methods on the Inventory object:")
    for item in items_added:
        print(f"    → player.inventory.add('{item}')")
    for item in items_removed:
        print(f"    → player.inventory.remove('{item}')")
    print(f"    → player.inventory.list_items()")
    print(f"    → player.inventory.count()")
    print(f"    → player.inventory.has_item(...)")
    print()
    print("-" * 50)
    print("  KEY OOP CONCEPTS PRACTICED")
    print("-" * 50)
    print()
    print("  ✓ Composition (HAS-A relationship)")
    print("      → Player HAS-A Inventory")
    print("      → More flexible than inheritance")
    print()
    print("  ✓ Class Variables (Inventory.MAX_CAPACITY)")
    print("      → Shared by ALL instances")
    print("      → Accessed via ClassName.variable")
    print()
    print("  ✓ Encapsulation")
    print("      → Inventory manages its own items list")
    print("      → Player doesn't need to know HOW it works")
    print()
    print("  ✓ Boolean Returns")
    print("      → add() returns True/False")
    print("      → has_item() returns True/False")
    print("      → Allows checking outcomes")
    print()
    print("=" * 50)
    print("  Next: Run validate.py for full automated checks")
    print("=" * 50)
    print()
